<script setup lang="ts">
import{nextTick,onBeforeUnmount,onMounted,ref}from'vue';import*as echarts from'echarts';import{api,type ApiResponse}from'@whaashop/shared';interface Analytics{conversations:number;questions:number;users:number;averageTurns:number;categories:{category:string;value:number}[];trend:{day:string;questions:number}[];hotQuestions:{question:string;frequency:number;lastAskedAt:string}[]}const data=ref<Analytics>({conversations:0,questions:0,users:0,averageTurns:0,categories:[],trend:[],hotQuestions:[]}),days=ref(30),trendEl=ref<HTMLElement>(),categoryEl=ref<HTMLElement>();let trendChart:echarts.ECharts|undefined,categoryChart:echarts.ECharts|undefined;const labels:Record<string,string>={ORDER:'订单咨询',LOGISTICS:'物流收货',AFTER_SALES:'退款售后',PAYMENT:'支付问题',PRODUCT:'商品咨询',ACCOUNT:'账户地址',OTHER:'其他问题'};async function load(){data.value=(await api.get<ApiResponse<Analytics>>('/admin/customer-service/analytics',{params:{days:days.value}})).data.data;await nextTick();trendChart??=echarts.init(trendEl.value!);categoryChart??=echarts.init(categoryEl.value!);trendChart.setOption({tooltip:{trigger:'axis'},grid:{left:42,right:20,bottom:35,top:25},xAxis:{type:'category',data:data.value.trend.map(v=>v.day)},yAxis:{type:'value',minInterval:1},series:[{type:'line',smooth:true,areaStyle:{color:'#d9ecff'},lineStyle:{color:'#409eff',width:3},itemStyle:{color:'#409eff'},data:data.value.trend.map(v=>v.questions)}]});categoryChart.setOption({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['42%','68%'],center:['50%','44%'],label:{formatter:'{b}\n{c} 条'},data:data.value.categories.map(v=>({name:labels[v.category]??v.category,value:v.value}))}]})}onMounted(load);onBeforeUnmount(()=>{trendChart?.dispose();categoryChart?.dispose()});
</script>
<template><div class="toolbar"><div><h2>客服问题分析</h2><p class="page-note">基于用户与智能客服的真实对话数据，识别高频咨询和服务趋势。</p></div><el-select v-model="days" style="width:140px" @change="load"><el-option label="近 7 天" :value="7"/><el-option label="近 30 天" :value="30"/><el-option label="近 90 天" :value="90"/></el-select></div><div class="cards"><div class="card"><b>咨询会话</b><h2>{{data.conversations}}</h2></div><div class="card"><b>用户问题</b><h2>{{data.questions}}</h2></div><div class="card"><b>咨询用户</b><h2>{{data.users}}</h2></div><div class="card"><b>平均对话轮次</b><h2>{{data.averageTurns}}</h2></div></div><div class="cs-chart-grid"><div class="panel"><h3>问题趋势</h3><div ref="trendEl" class="cs-chart"/></div><div class="panel"><h3>问题类型分布</h3><div ref="categoryEl" class="cs-chart"/></div></div><div class="panel cs-hot-panel"><h3>高频问题 Top 10</h3><el-table :data="data.hotQuestions"><el-table-column type="index" label="排名" width="80"/><el-table-column prop="question" label="用户问题" min-width="360" show-overflow-tooltip/><el-table-column prop="frequency" label="咨询次数" width="120"/><el-table-column prop="lastAskedAt" label="最近咨询" width="190"/></el-table><el-empty v-if="!data.hotQuestions.length" description="当前周期暂无客服对话"/></div></template>
